css:
.atlassim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2f3a45;
    background: linear-gradient(160deg, #f4f7f6 0%, #eaf1f0 60%, #e4eeef 100%);
    border-radius: 18px;
}

.atlassim-container * {
    box-sizing: border-box;
}

.atlassim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14746a 0%, #1f8f7d 55%, #3aa893 100%);
    color: #f3fffb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 36px rgba(20, 116, 106, 0.28);
}

.atlassim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.atlassim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffe6b0;
    background: rgba(255, 230, 176, 0.16);
    border: 1px solid rgba(255, 230, 176, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.atlassim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3f5ef;
}

.atlassim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #506470;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.atlassim-period-counter #currentDay,
.atlassim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14746a;
}

.atlassim-round-name {
    background: rgba(20, 116, 106, 0.12);
    color: #14746a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.atlassim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5641a;
    background: rgba(228, 138, 47, 0.14);
    border: 1px solid rgba(228, 138, 47, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.atlassim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.atlassim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde8e5;
    box-shadow: 0 6px 16px rgba(47, 58, 69, 0.06);
    border-top: 4px solid #3aa893;
}

.atlassim-card-engage { border-top-color: #1f8f7d; }
.atlassim-card-meaning { border-top-color: #d99022; }
.atlassim-card-perf { border-top-color: #3672c4; }
.atlassim-card-risk { border-top-color: #d4604f; }

.atlassim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7b8b94;
}

.atlassim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #233038;
    font-variant-numeric: tabular-nums;
}

.atlassim-card-engage .atlassim-value { color: #1f8f7d; }
.atlassim-card-meaning .atlassim-value { color: #c47e12; }
.atlassim-card-perf .atlassim-value { color: #3672c4; }
.atlassim-card-risk .atlassim-value { color: #d4604f; }

.atlassim-sublabel {
    font-size: 0.76rem;
    color: #8294a0;
    line-height: 1.35;
}

.atlassim-engage-high { border-top-color: #169c63; }
.atlassim-engage-high .atlassim-value { color: #169c63; }
.atlassim-engage-low { border-top-color: #d4604f; }
.atlassim-engage-low .atlassim-value { color: #d4604f; }

.atlassim-risk-high { border-top-color: #c33d2c; }
.atlassim-risk-high .atlassim-value { color: #c33d2c; }
.atlassim-risk-low { border-top-color: #169c63; }
.atlassim-risk-low .atlassim-value { color: #169c63; }

.atlassim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde8e5;
    color: #41525c;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.atlassim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #14746a;
}

.atlassim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f8f7d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(47, 58, 69, 0.06);
}

.atlassim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.atlassim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1a2730;
    margin-bottom: 6px;
}

.atlassim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #455660;
}

.atlassim-briefing-text strong { color: #14746a; }
.atlassim-briefing-text em { color: #b5641a; font-style: italic; }

.atlassim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde8e5;
    box-shadow: 0 6px 16px rgba(47, 58, 69, 0.06);
}

.atlassim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1a2730;
    border-bottom: 2px solid #e7efed;
    padding-bottom: 8px;
}

.atlassim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #34444d;
    margin: 14px 0 6px;
}

.atlassim-container select,
.atlassim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c7d6d1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7faf9;
    color: #2b3a42;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.atlassim-container select:focus,
.atlassim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f8f7d;
    box-shadow: 0 0 0 3px rgba(31, 143, 125, 0.16);
}

.atlassim-container select option {
    background-color: #ffffff;
    color: #2b3a42;
}

.atlassim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f8f7d;
}

.atlassim-range-readout,
.atlassim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #607480;
    margin-top: 4px;
}

.atlassim-range-readout span:last-child,
.atlassim-alloc-readout span:nth-child(2) {
    color: #14746a;
    font-weight: 800;
}

.atlassim-hint {
    font-size: 0.8rem;
    color: #8294a0;
    margin-top: 4px;
    line-height: 1.4;
}

.atlassim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.atlassim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f9f7;
    border: 1px solid #d9e7e2;
    border-radius: 9px;
    padding: 8px 12px;
}

.atlassim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #41525c;
}

.atlassim-alloc-row input[type="number"] {
    width: 84px;
    flex: 0 0 84px;
}

.atlassim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.atlassim-container .btn-primary {
    background: linear-gradient(135deg, #14746a 0%, #2aa28d 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(20, 116, 106, 0.32);
}

.atlassim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.atlassim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c7d6d1;
    color: #607480;
    background: transparent;
}

.atlassim-coach {
    background: linear-gradient(160deg, #fbf6ec 0%, #f7efe0 100%);
    color: #4a4233;
    border: 1px solid #ecdcbf;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(181, 100, 26, 0.08);
}

.atlassim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b5641a;
    margin-bottom: 8px;
}

.atlassim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #5a503f;
}

.atlassim-coach-body strong { color: #14746a; }
.atlassim-coach-body em { color: #b5641a; font-style: italic; }

.atlassim-history,
.atlassim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde8e5;
    box-shadow: 0 6px 16px rgba(47, 58, 69, 0.06);
}

.atlassim-history h3,
.atlassim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1a2730;
}

.atlassim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #41525c;
}

.atlassim-container table#usfHistoryTable th {
    background: #f1f7f5;
    color: #14746a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d9e7e2;
}

.atlassim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eaf1ef;
    color: #455660;
}

.atlassim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbfa;
}

.atlassim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .atlassim-container {
        padding: 14px;
    }
    .atlassim-header h1 {
        font-size: 1.7rem;
    }
    .atlassim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .atlassim-value {
        font-size: 2.1rem;
    }
    .atlassim-clock {
        margin-left: 0;
    }
    .atlassim-period-counter {
        font-size: 0.88rem;
    }
    .atlassim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .atlassim-alloc-row {
        flex-wrap: wrap;
    }
    .atlassim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .atlassim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .ats-cm-*) */
.ats-cm { margin-top: 8px; }
.ats-cm-incomplete { text-align: center; color: #14463f; font-size: 1rem; padding: 18px; }
.ats-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.ats-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0f5a51 0%, #14746a 55%, #1f8f7d 140%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(20,116,106,0.28); }
.ats-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.ats-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.ats-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #bfe7e0; }
.ats-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #f4faf8; border: 1px solid #dde8e5; border-radius: 14px; padding: 14px 20px; }
.ats-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6f9188; }
.ats-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #14463f; margin-top: 4px; line-height: 1.15; }
.ats-cm-section { margin-bottom: 16px; }
.ats-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #14746a; margin-bottom: 8px; border-bottom: 1px solid #dde8e5; padding-bottom: 4px; }
.ats-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ats-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.ats-cm-ok { background: #e2f2ee; color: #14463f; border-color: #bfe0d8; }
.ats-cm-no { background: #f8e7e2; color: #a3462a; border-color: #eec9bd; }
.ats-cm-ico { font-weight: 800; }
.ats-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.ats-cm-kpi { background: #fbfdfc; border: 1px solid #dde8e5; border-radius: 12px; padding: 12px 10px; text-align: center; }
.ats-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #14746a; line-height: 1; }
.ats-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #234; margin-top: 6px; }
.ats-cm-kpi-sub { font-size: 0.68rem; color: #6f9188; margin-top: 2px; }
.ats-cm-insights { margin: 0; padding-left: 20px; color: #143b35; }
.ats-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .ats-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

