(function() {
    'use strict';

    class AtlasAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Servant Leader`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Polder Digital / Atlas squad).
            this.OOO_CAP = 8;             // 8 one-on-one hours to allocate in Round 1
            this.PENALTY = 180;           // EUR 180k milestone-slip penalty (in EUR k)
            this.BACKFILL = 95;           // EUR 95k star backfill + re-ramp (in EUR k)
            this.DEV_HOURS = 40;          // ~40 development hours promised to 2 high-potentials

            // Concept truths (the servant-leadership "right" reading).
            this.TRUE_ROOT = `meaning`;
            this.TRUE_UNDER = `life`;
            this.TRUE_STAR = `empower`;
            this.TRUE_PERF = `carecuhold`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engage: 71,            // team engagement pulse (0-100), baseline 71
                    meaning: 6.1,          // meaningfulness score (0-10), baseline 6.1
                    perf: 62,              // performance index toward 19 June milestone (0-100)
                    risk: 48,              // turnover risk (0-100), lower better
                    starGone: false,       // did the star exit?
                    milestone: `pending`,  // pending | hit | partial | slipped
                    spiralUp: false,       // upward spiral engaged
                    spiralDown: false,     // downward spiral triggered
                    devBroken: false,      // development promise broken
                    oneSizeFits: false,    // applied one fixed style to all three
                    netCost: 0,            // accumulated EUR k cost (penalty + backfill)
                    engageHistory: [71],
                    perfHistory: [62],
                    riskHistory: [48],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately directive / symptom-level mix —
                // a blind click-through must NOT auto-win.
                state.decisions = {
                    root: `lazy`,
                    under: `discipline`,
                    oooStar: 2,
                    oooUnder: 2,
                    oooHipo: 2,
                    oooRest: 2,
                    starMove: `direct`,
                    dev: `cancel`,
                    blocker: 50,
                    perfMove: `plan`,
                    standard: `ignore`,
                    capacity: 50,
                    finalPush: `crunch`,
                    partner: `datebrag`,
                    philosophy: `results`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rt = document.getElementById(`rootInput`);
                const un = document.getElementById(`underInput`);
                const s = document.getElementById(`oooStarInput`);
                const u = document.getElementById(`oooUnderInput`);
                const h = document.getElementById(`oooHipoInput`);
                const r = document.getElementById(`oooRestInput`);
                if (rt) decisions.root = rt.value;
                if (un) decisions.under = un.value;
                if (s) decisions.oooStar = parseInt(s.value, 10);
                if (u) decisions.oooUnder = parseInt(u.value, 10);
                if (h) decisions.oooHipo = parseInt(h.value, 10);
                if (r) decisions.oooRest = parseInt(r.value, 10);
                const parts = [decisions.oooStar, decisions.oooUnder, decisions.oooHipo, decisions.oooRest];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) { warn(`warn_ooo_negative`); return false; }
                const total = decisions.oooStar + decisions.oooUnder + decisions.oooHipo + decisions.oooRest;
                if (total !== this.OOO_CAP) { warn(`warn_ooo_total`); return false; }
            } else if (round === 2) {
                const sm = document.getElementById(`starMoveInput`);
                const dv = document.getElementById(`devInput`);
                const bl = document.getElementById(`blockerInput`);
                if (sm) decisions.starMove = sm.value;
                if (dv) decisions.dev = dv.value;
                if (bl) decisions.blocker = parseInt(bl.value, 10);
                if (!Number.isFinite(decisions.blocker) || decisions.blocker < 0 || decisions.blocker > 100) {
                    warn(`warn_blocker_range`); return false;
                }
            } else if (round === 3) {
                const pm = document.getElementById(`perfMoveInput`);
                const st = document.getElementById(`standardInput`);
                const cp = document.getElementById(`capacityInput`);
                if (pm) decisions.perfMove = pm.value;
                if (st) decisions.standard = st.value;
                if (cp) decisions.capacity = parseInt(cp.value, 10);
                if (!Number.isFinite(decisions.capacity) || decisions.capacity < 0 || decisions.capacity > 100) {
                    warn(`warn_capacity_range`); return false;
                }
            } else if (round === 4) {
                const fp = document.getElementById(`finalPushInput`);
                const pa = document.getElementById(`partnerInput`);
                const ph = document.getElementById(`philosophyInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fp) decisions.finalPush = fp.value;
                if (pa) decisions.partner = pa.value;
                if (ph) decisions.philosophy = ph.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (was computed only in getPerformanceSummary and discarded).
            const engage = Math.round(ds.engage);
            const meaning = Math.round(ds.meaning * 10) / 10;
            const perf = Math.round(ds.perf);
            const risk = Math.round(ds.risk);
            return Math.round(engage * 0.28 + (meaning * 10) * 0.24 + perf * 0.28 + (100 - risk) * 0.20);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let engageDelta = 0, meaningDelta = 0, perfDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose ROOT not symptom (Common Error 4: symptom over cause).
                switch (d.root) {
                    case `meaning`: meaningDelta += 0.5; engageDelta += 4; riskDelta -= 5; coachKey = `coach_r1_root`; break;
                    case `unknown`: engageDelta += 1; coachKey = `coach_r1_unknown`; break;
                    case `lazy`: engageDelta -= 3; riskDelta += 6; coachKey = `coach_r1_lazy`; break;
                    case `pay`: engageDelta -= 1; riskDelta += 3; coachKey = `coach_r1_pay`; break;
                }
                // The underperformer's root — caregiving cause, not skill/discipline.
                switch (d.under) {
                    case `life`: meaningDelta += 0.3; engageDelta += 3; riskDelta -= 4; if (d.root === `meaning`) coachKey = `coach_r1_sharp`; break;
                    case `skill`: perfDelta -= 2; riskDelta += 3; break;
                    case `discipline`: engageDelta -= 3; riskDelta += 5; coachKey = `coach_r1_discipline`; break;
                    case `noroot`: engageDelta -= 4; riskDelta += 6; coachKey = `coach_r1_noroot`; break;
                }
                // One-on-one time: investing in the three at-risk fronts (star, underperformer,
                // high-potentials) builds the leading indicators; starving them raises risk.
                const investedAtRisk = d.oooStar + d.oooUnder + d.oooHipo;
                if (d.oooStar >= 2) { engageDelta += 2; riskDelta -= 3; }
                else { riskDelta += 3; }
                if (d.oooUnder >= 2) { meaningDelta += 0.2; riskDelta -= 2; }
                if (d.oooHipo >= 2) { engageDelta += 2; riskDelta -= 3; }
                else { riskDelta += 2; }
                if (d.oooRest >= 1) { engageDelta += 1; }
                if (investedAtRisk <= 3) { engageDelta -= 3; riskDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r1_thinspread`; }

                summaryKey = (d.root === `meaning` && d.under === `life`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The disengaging EXPERT needs empowerment, not control (Common Error 1).
                const blockerShare = d.blocker / 100;     // % of week clearing the path vs adding oversight
                switch (d.starMove) {
                    case `empower`:
                        meaningDelta += 1.0; engageDelta += 6; perfDelta += 4; riskDelta -= 10;
                        coachKey = `coach_r2_empower`;
                        break;
                    case `support`:
                        meaningDelta += 0.2; engageDelta += 1; riskDelta -= 2; coachKey = `coach_r2_support`;
                        break;
                    case `direct`:
                        // Tightening control on a disengaging expert deepens the downward spiral.
                        meaningDelta -= 0.7; engageDelta -= 5; perfDelta += 3; riskDelta += 12;
                        ds.spiralDown = true; coachKey = `coach_r2_direct`;
                        break;
                }
                // Removing blockers (standing back) helps an expert; oversight harms one.
                if (d.starMove !== `direct`) {
                    meaningDelta += (blockerShare - 0.5) * 1.2;
                    engageDelta += (blockerShare - 0.5) * 6;
                    riskDelta -= (blockerShare - 0.5) * 6;
                    if (blockerShare <= 0.25) { coachKey = `coach_r2_oversight`; }
                }

                // The development promise — a job RESOURCE at peak demand (Common Error 3).
                switch (d.dev) {
                    case `protect`: meaningDelta += 0.8; engageDelta += 5; riskDelta -= 9; perfDelta -= 2; break;
                    case `halve`: meaningDelta += 0.1; engageDelta += 1; riskDelta -= 1; perfDelta += 1; break;
                    case `cancel`:
                        meaningDelta -= 0.8; engageDelta -= 6; riskDelta += 12; perfDelta += 3;
                        ds.devBroken = true; if (coachKey !== `coach_r2_direct`) coachKey = `coach_r2_devcancel`;
                        break;
                }

                summaryKey = (d.starMove === `empower` && d.dev !== `cancel`) ? `sum_r2_good` :
                             (d.starMove === `direct` && d.dev === `cancel` ? `sum_r2_directive` : `sum_r2_weak`);
            } else if (round === 3) {
                // Performance with care: hold the bar AND diagnose cause (Common Error 2 & 4).
                const capShare = d.capacity / 100;
                switch (d.perfMove) {
                    case `carecuhold`:
                        meaningDelta += 0.9; engageDelta += 6; perfDelta += 5; riskDelta -= 9;
                        ds.spiralUp = true; coachKey = `coach_r3_carehold`;
                        break;
                    case `plan`:
                        // Escalating without diagnosing cause signals that struggle is punished.
                        meaningDelta -= 0.6; engageDelta -= 5; perfDelta += 2; riskDelta += 9;
                        ds.spiralDown = true; coachKey = `coach_r3_plan`;
                        break;
                    case `ignore`:
                        // Empowerment as abdication — the squad watches accountability vanish.
                        meaningDelta -= 0.4; engageDelta -= 4; perfDelta -= 6; riskDelta += 6;
                        coachKey = `coach_r3_abdicate`;
                        break;
                }
                // Where the bar is set — clear & humane is the servant-leadership standard.
                switch (d.standard) {
                    case `clear`: meaningDelta += 0.5; engageDelta += 3; perfDelta += 3; riskDelta -= 4; break;
                    case `drop`: perfDelta -= 5; engageDelta -= 1; coachKey = (coachKey === `coach_default` ? `coach_r3_dropbar` : coachKey); break;
                    case `ignore`: meaningDelta -= 0.3; riskDelta += 4; coachKey = (coachKey === `coach_default` ? `coach_r3_holdrigid` : coachKey); break;
                }
                // Capacity at the milestone: too little slips it, too much burns the squad.
                if (capShare >= 0.45 && capShare <= 0.75) { perfDelta += 6; }
                else if (capShare < 0.35) { perfDelta -= 6; coachKey = (coachKey === `coach_default` ? `coach_r3_undercap` : coachKey); }
                else if (capShare > 0.85) { perfDelta += 3; engageDelta -= 4; riskDelta += 5; coachKey = (coachKey === `coach_default` ? `coach_r3_overcap` : coachKey); }
                else { perfDelta += 3; }

                summaryKey = (d.perfMove === `carecuhold` && d.standard === `clear`) ? `sum_r3_good` :
                             (d.perfMove === `plan` ? `sum_r3_punitive` :
                             (d.perfMove === `ignore` ? `sum_r3_abdicate` : `sum_r3_weak`));
            } else if (round === 4) {
                // Final push: convert meaning into performance, sustainably (Common Error: feelings over output).
                switch (d.finalPush) {
                    case `sustainable`: perfDelta += 6; engageDelta += 3; meaningDelta += 0.4; riskDelta -= 4; coachKey = `coach_r4_sustainable`; break;
                    case `crunch`: perfDelta += 7; engageDelta -= 6; meaningDelta -= 0.5; riskDelta += 10; ds.spiralDown = true; coachKey = `coach_r4_crunch`; break;
                    case `protect`: perfDelta -= 7; engageDelta += 4; riskDelta -= 2; coachKey = `coach_r4_protectonly`; break;
                }
                // The partner story — honest trade-off framing reads as leadership maturity.
                switch (d.partner) {
                    case `tradeoff`: engageDelta += 2; meaningDelta += 0.2; coachKey = (d.finalPush === `sustainable` ? `coach_r4_mature` : coachKey); break;
                    case `datebrag`: engageDelta -= 2; riskDelta += 2; break;
                    case `feelings`: perfDelta -= 2; coachKey = (coachKey === `coach_default` ? `coach_r4_feelings` : coachKey); break;
                }
                // Operating philosophy — serve AND hold is the integrated frame.
                switch (d.philosophy) {
                    case `servant`: meaningDelta += 0.5; engageDelta += 4; perfDelta += 3; riskDelta -= 5; break;
                    case `results`: meaningDelta -= 0.4; engageDelta -= 3; riskDelta += 5; coachKey = (coachKey === `coach_default` ? `coach_r4_resultsonly` : coachKey); break;
                    case `harmony`: perfDelta -= 4; riskDelta += 2; coachKey = (coachKey === `coach_default` ? `coach_r4_harmonyonly` : coachKey); break;
                }
                if (d.conviction >= 60) { perfDelta += 3; engageDelta += 2; }
                else if (d.conviction <= 25) { engageDelta -= 3; }

                summaryKey = (d.finalPush === `sustainable` && d.philosophy === `servant`) ? `sum_r4_good` :
                             (d.finalPush === `crunch` ? `sum_r4_crunch` :
                             (d.finalPush === `protect` ? `sum_r4_soft` : `sum_r4_weak`));
            }

            // One-size-fits-all detector (Common Error 5): same stance for expert, hipos, junior.
            // Checked once the relevant decisions exist (round >= 3).
            if (round >= 3) {
                const directiveAll = (d.starMove === `direct` && d.dev === `cancel` && d.perfMove === `plan`);
                const softAll = (d.starMove === `support` && d.dev === `protect` && d.perfMove === `ignore`);
                if (directiveAll || softAll) {
                    ds.oneSizeFits = true;
                    engageDelta -= 3; riskDelta += 4;
                    if (round === 3) coachKey = `coach_onesize`;
                }
            }

            // Apply deltas (engagement/perf/risk 0-100; meaning 0-10).
            ds.engage = Math.max(0, Math.min(100, Math.round(ds.engage + engageDelta)));
            ds.meaning = Math.max(0, Math.min(10, Math.round((ds.meaning + meaningDelta) * 10) / 10));
            ds.perf = Math.max(0, Math.min(100, Math.round(ds.perf + perfDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            // The star's stay/leave decision resolves on the accumulated downward spiral + risk.
            if (!ds.starGone && round >= 2) {
                const exitPressure = (ds.spiralDown ? 1 : 0) + (ds.risk >= 62 ? 1 : 0) + (ds.meaning <= 5.2 ? 1 : 0);
                if (exitPressure >= 2) {
                    ds.starGone = true;
                    ds.netCost += this.BACKFILL;   // EUR 95k backfill + re-ramp
                    ds.perf = Math.max(0, ds.perf - 14);   // critical-path dependency: milestone slips
                    coachKey = `coach_starexit`;
                }
            }

            // Milestone outcome resolves in the final round.
            if (round === 4) {
                if (ds.starGone || ds.perf < 55) {
                    ds.milestone = `slipped`;
                    ds.netCost += this.PENALTY;    // EUR 180k contracted penalty
                } else if (ds.perf >= 75 && ds.engage >= 60) {
                    ds.milestone = `hit`;
                } else {
                    ds.milestone = `partial`;
                }
            }

            ds.engageHistory.push(ds.engage);
            ds.perfHistory.push(ds.perf);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                engage: ds.engage,
                engageDelta: Math.round(engageDelta),
                meaning: ds.meaning,
                meaningDelta: Math.round(meaningDelta * 10) / 10,
                perf: ds.perf,
                perfDelta: Math.round(perfDelta),
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                starGone: ds.starGone,
                milestone: ds.milestone,
                netCost: ds.netCost,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR thousands: English "€95k", Spanish "95 k€".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Math.round(v));
            if (lang === `es`) {
                return `${sign}${abs.toLocaleString(`es-ES`)} k€`;
            }
            return `${sign}€${abs.toLocaleString(`en-US`)}k`;
        }

        _fmtMilestone(code) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return t(`milestone_` + (code || `pending`));
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => {
                const card = document.querySelector(`.atlassim-card-engage`);
                if (card) {
                    card.classList.toggle(`atlassim-engage-high`, Number(v) >= 78);
                    card.classList.toggle(`atlassim-engage-low`, Number(v) <= 60);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`meaningDisplay`, `domainState.meaning`, (v) => Number(v).toFixed(1));
            uiManager.bind(`perfDisplay`, `domainState.perf`, (v) => Math.round(Number(v)));
            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const card = document.querySelector(`.atlassim-card-risk`);
                if (card) {
                    card.classList.toggle(`atlassim-risk-high`, Number(v) >= 62);
                    card.classList.toggle(`atlassim-risk-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });

            // Blocker slider readout.
            const bl = document.getElementById(`blockerInput`);
            const blReadout = document.getElementById(`blockerReadout`);
            if (bl && blReadout) {
                blReadout.textContent = bl.value;
                bl.addEventListener(`input`, function() { blReadout.textContent = bl.value; });
            }

            // Capacity slider readout.
            const cp = document.getElementById(`capacityInput`);
            const cpReadout = document.getElementById(`capacityReadout`);
            if (cp && cpReadout) {
                cpReadout.textContent = cp.value;
                cp.addEventListener(`input`, function() { cpReadout.textContent = cp.value; });
            }

            // One-on-one hours live total (must hit 8 h).
            const oooIds = [`oooStarInput`, `oooUnderInput`, `oooHipoInput`, `oooRestInput`];
            const oooReadout = document.getElementById(`oooReadout`);
            const budgetEl = document.getElementById(`budgetDisplay`);
            const recompute = function() {
                let total = 0;
                oooIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (oooReadout) oooReadout.textContent = total;
                if (budgetEl) budgetEl.textContent = total + ` / ` + self.OOO_CAP + ` h`;
                const bar = document.querySelector(`.atlassim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.OOO_CAP) ? `#d4604f` : ``;
            };
            oooIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

