        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engageHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                atlasChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.engageHistory },
                        { data: ds.perfHistory },
                        { data: ds.riskHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const engage = Math.round(ds.engage);
            const meaning = Math.round(ds.meaning * 10) / 10;
            const perf = Math.round(ds.perf);
            const risk = Math.round(ds.risk);

            // Composite: engagement, meaningfulness (scaled to 100), performance, low risk.
            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const milestoneHit = ds.milestone === `hit`;
            const milestonePartial = ds.milestone === `partial`;
            const teamKept = engage >= 65 && risk <= 40 && !ds.starGone;
            const meaningful = meaning >= 6.5;
            const spiralUp = ds.spiralUp && !ds.spiralDown;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_adrift`;
            if (milestoneHit && teamKept && meaningful && composite >= 75) tierKey = `grade_servant`;
            else if (milestoneHit && teamKept) tierKey = `grade_delivered`;
            else if (milestoneHit && !teamKept) tierKey = `grade_hitdate`;
            else if (!milestoneHit && teamKept) tierKey = `grade_keptteam`;
            else if (ds.milestone === `slipped` && ds.starGone) tierKey = `grade_spiral`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (milestoneHit && teamKept && meaningful) insights.push(window.mySimulation.t(`insight_servant`));
            else if (ds.starGone) insights.push(window.mySimulation.t(`insight_starexit`));
            else if (ds.milestone === `slipped`) insights.push(window.mySimulation.t(`insight_slipped`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.devBroken) insights.push(window.mySimulation.t(`insight_devbroken`));
            if (ds.spiralDown) insights.push(window.mySimulation.t(`insight_spiraldown`));
            else if (spiralUp) insights.push(window.mySimulation.t(`insight_spiralup`));
            if (ds.oneSizeFits) insights.push(window.mySimulation.t(`insight_onesize`));
            if (milestoneHit && !teamKept) insights.push(window.mySimulation.t(`insight_pyrrhic`));
            if (meaning >= 7 && perf < 60) insights.push(window.mySimulation.t(`insight_meaningnoperf`));

            return {
                engage: engage,
                meaning: meaning,
                perf: perf,
                risk: risk,
                milestone: this._fmtMilestone(ds.milestone),
                starGone: ds.starGone,
                netCost: ds.netCost,
                teamKept: teamKept,
                milestoneHit: milestoneHit,
                meaningful: meaningful,
                riskOk: risk <= 40,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="ats-cm"><p class="ats-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="ats-cm-chip ` + (ok ? `ats-cm-ok` : `ats-cm-no`) + `">` +
                `<span class="ats-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="ats-cm-kpi"><div class="ats-cm-kpi-val">` + val +
                `</div><div class="ats-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="ats-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="ats-cm">` +
  `<div class="ats-cm-head">` +
    `<div class="ats-cm-score"><div class="ats-cm-score-num">` + Math.round(s.composite) +
       `<span class="ats-cm-score-den">/100</span></div>` +
       `<div class="ats-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="ats-cm-verdict"><div class="ats-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="ats-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="ats-cm-section"><div class="ats-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="ats-cm-chips">` + chip(!!s.milestoneHit, t(`cm_t_milestone`)) + chip(!!s.teamKept, t(`cm_t_team`)) +
      chip(!!s.meaningful, t(`cm_t_meaning`)) + chip(!!s.riskOk, t(`cm_t_risk`)) + `</div></div>` +
  `<div class="ats-cm-section"><div class="ats-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="ats-cm-kpis">` +
      kpi(t(`cm_lbl_engage`), Math.round(s.engage), t(`cm_sub_engage`)) +
      kpi(t(`cm_lbl_meaning`), Number(s.meaning).toFixed(1), t(`cm_sub_meaning`)) +
      kpi(t(`cm_lbl_perf`), Math.round(s.perf), t(`cm_sub_perf`)) +
      kpi(t(`cm_lbl_risk`), Math.round(s.risk), t(`cm_sub_risk`)) +
    `</div></div>` +
  (insights ? `<div class="ats-cm-section"><div class="ats-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="ats-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.starGone) return window.mySimulation.t(`hint_starexit`);
            if (ds.spiralDown) return window.mySimulation.t(`hint_spiraldown`);
            if (ds.devBroken && state.currentPeriod >= 2) return window.mySimulation.t(`hint_devbroken`);
            if (ds.risk >= 62) return window.mySimulation.t(`hint_risk`);
            if (state.currentPeriod >= 3 && ds.perf < 55) return window.mySimulation.t(`hint_perf`);
            if (ds.engage >= 72 && ds.perf >= 70 && ds.risk <= 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

