                { key: `results.engage`, label: `Engagement`, i18nKey: `col_engage`, formatter: (v) => Math.round(v) },
                { key: `results.meaning`, label: `Meaning`, i18nKey: `col_meaning`, formatter: (v) => Number(v).toFixed(1) },
                { key: `results.perf`, label: `Performance`, i18nKey: `col_perf`, formatter: (v) => Math.round(v) },
